tool_calls:
python3 - <<'PY'
from collections import Counter
p='/var/log/app.log'
c=Counter()
with open(p, encoding='utf-8', errors='replace') as f:
    for line in f:
        for level in ('INFO','WARN','ERROR'):
            if level in line:
                c[level]+=1
                break
for level in ('INFO','WARN','ERROR'):
    print(f'{level}: {c[level]}')
PY

